    return "\n".join(out)


def segments(cmd):
    """Split on control operators outside quotes. Returns (segments, ends_in_background)."""
    segs, cur, i, n, q = [], [], 0, len(cmd), None
    bg = False
    while i < n:
        c = cmd[i]
        if q:
            cur.append(c)
            if c == "\\" and q == '"' and i + 1 < n:
                cur.append(cmd[i + 1])
                i += 1
            elif c == q:
                q = None
        elif c in "'\"":
            q = c
            cur.append(c)
        elif c == "\\" and i + 1 < n:
            cur.append(c + cmd[i + 1])
            i += 1
        elif c == "#" and (not cur or cur[-1] in " \t"):
            while i < n and cmd[i] != "\n":
